prompts+=( '{"short_description":"A dark ceramic mug of hot tea steaming on a rustic wooden table by a rainy window in a cozy interior, where random phenomena subtly align into a barely perceptible pareidolia of a distorted woman'\''s face profile.","objects":[{"description":"A dark ceramic mug of hot tea steaming on a rustic wooden table by the window. The steam curls on one side, widening with height, subtly resembling a nose.","location":"center of the table","relationship":"On the table by the window","relative_size":"medium","shape_and_color":"Dark ceramic","texture":"Glossy ceramic with steam","appearance_details":"Steam curl that widens with height","number_of_objects":1},{"description":"An empty wooden chair","location":"left of the table","relationship":"Beside the table","relative_size":"medium","shape_and_color":"Wood","texture":"Wood grain","number_of_objects":1},{"description":"A lit candle in a brass holder","location":"right side of the table","relationship":"On the table","relative_size":"small","shape_and_color":"Brass with warm flame","texture":"Brass","appearance_details":"Lit flame","number_of_objects":1},{"description":"A rainy window pane with thick water droplets and mostly vertical thin rivulets that subtly read as hair, a tree branch reading as a forehead, red car taillights reading as lips and blue neon street signs reading as an eye, all as random real items with no actual face or silhouette","location":"window behind the table","relationship":"Outside the room","relative_size":"large","shape_and_color":"Blue neon, red taillights, orange and yellow lights","texture":"Rain droplets and rivulets","appearance_details":"Extremely low-contrast pareidolia of a distorted woman'\''s face profile with no solid lines and no horizontal lines","number_of_objects":1}],"background_setting":"A rainy evening outside the window with blurred orange and yellow city lights creating bokeh.","lighting":{"conditions":"Moody atmospheric lighting; all light and shadow come from real items","direction":"From the candle and the city lights","shadows":"No forced silhouette shadows"},"aesthetics":{"composition":"Cinematic composition contrasting the cozy interior with the rainy evening outside.","color_scheme":"Warm orange and yellow with cool blue neon and red taillights","mood_atmosphere":"Melancholic, cozy","preference_score":"very high","aesthetic_score":"very high"},"photographic_characteristics":{"depth_of_field":"Shallow depth of field with bokeh outside","focus":"Sharp on the mug","camera_angle":"Eye level","lens_focal_length":"Standard lens"},"style_medium":"photograph","artistic_style":"Cinematic filmic grain photography"}' )

# ---- QUEUE JOBS ------------------------------------------------------------
if [[ ${#prompts[@]} -ne ${#ids[@]} ]]; then
  echo "❌ ids[] and prompts[] length mismatch — fix the script." >&2
  exit 1
fi

for (( i=0; i<${#prompts[@]}; i++ )); do
  queue_job $((i+1)) "${ids[$i]}" "${prompts[$i]}"
done

echo "✅ All ${#prompts[@]} jobs queued in scheduler"
